#!/usr/bin/env python
"""Per-task live-test budget for harness workers, generated by the harness-loop skill.

A project's slow test runner calls ``charge()`` before every expensive run (a live editor run, an e2e suite).
The driver puts its own directory in HARNESS_HOME for worker sessions, so the runner needs no copy of this file:

    home = os.environ.get("HARNESS_HOME")
    if home:
        sys.path.insert(0, home)
        import run_budget
        ok, msg = run_budget.charge("full --only TMS.Full.Warden")
        if not ok:
            print(msg)
            sys.exit(3)

Outside a harness worker session (no HARNESS_UNIT_FOLDER in the environment) it always allows the run, so people
and orchestrators are never limited. Inside a worker session, it counts runs per task per session in
<run folder>/RUN-LEDGER.json, where the task is the one marked [~] in TASKS.md (else the first open one), and
refuses once the task has used HARNESS_RUN_BUDGET runs. Runs made by the harness gate (HARNESS_GATE=1) are never
charged: the gate is the unit's one regression run, and it is limited separately.

    python run_budget.py status      # show this session's ledger (inside a worker session)
"""

from __future__ import annotations

import datetime as dt
import json
import os
import re
import sys
from pathlib import Path

TASK_RE = re.compile(r"^- \[( |x|~)\] (T\d+)\b")


def _folder() -> Path | None:
    f = os.environ.get("HARNESS_UNIT_FOLDER")
    return Path(f) if f else None


def current_task(folder: Path) -> str:
    """The [~] task, else the first open task, else 'unit'."""
    try:
        lines = (folder / "TASKS.md").read_text(encoding="utf-8").splitlines()
    except OSError:
        return "unit"
    tasks = [m.groups() for m in map(TASK_RE.match, lines) if m]
    for state, tid in tasks:
        if state == "~":
            return tid
    for state, tid in tasks:
        if state == " ":
            return tid
    return "unit"


def _load(folder: Path) -> dict:
    try:
        return json.loads((folder / "RUN-LEDGER.json").read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}


def _save(folder: Path, ledger: dict) -> None:
    tmp = folder / "RUN-LEDGER.tmp"
    tmp.write_text(json.dumps(ledger, indent=1), encoding="utf-8")
    os.replace(tmp, folder / "RUN-LEDGER.json")


def session_ledger(folder: Path) -> dict:
    """This session's entry: {task: {"runs": n, "labels": [...]}}. Older sessions are kept for the record."""
    ledger = _load(folder)
    return ledger.get(os.environ.get("HARNESS_SESSION", "0"), {})


def charge(label: str = "") -> tuple[bool, str]:
    folder = _folder()
    if folder is None or os.environ.get("HARNESS_GATE") == "1":
        return True, ""
    budget = int(os.environ.get("HARNESS_RUN_BUDGET") or 0)
    if budget <= 0:
        return True, ""
    session = os.environ.get("HARNESS_SESSION", "0")
    task = current_task(folder)
    ledger = _load(folder)
    entry = ledger.setdefault(session, {}).setdefault(task, {"runs": 0, "labels": []})
    if entry["runs"] >= budget:
        return False, (
            f"RUN BUDGET SPENT: {task} has used {entry['runs']} of {budget} live test runs this session; this run "
            "was refused. Do not retry or work around it. Diagnose from the logs and reports of the runs you already "
            "have. Then either fix the cause with one more batched change and let the gate check it, or record the gap "
            "in HANDOFF.md (and a Needs item if it blocks the task) and move on. Runs so far: "
            + "; ".join(entry["labels"][-budget:]))
    entry["runs"] += 1
    entry["labels"].append(f"{dt.datetime.now():%H:%M} {label}".strip())
    _save(folder, ledger)
    return True, f"run budget: {task} run {entry['runs']} of {budget} this session"


def main(argv: list[str]) -> int:
    folder = _folder()
    if folder is None:
        print("not in a harness worker session (HARNESS_UNIT_FOLDER unset): no budget applies")
        return 0
    if argv[:1] == ["status"]:
        budget = os.environ.get("HARNESS_RUN_BUDGET") or "unlimited"
        print(f"session {os.environ.get('HARNESS_SESSION', '0')}, budget {budget} runs per task, "
              f"current task {current_task(folder)}")
        for task, e in session_ledger(folder).items():
            print(f"  {task}: {e['runs']} run(s): " + "; ".join(e["labels"]))
        return 0
    print(__doc__)
    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
